# g4 gate runner. generated by tools/kaggle_gate.py, don't edit the copy in kaggle/runs/.
#
# boots the scorer's vLLM config once, then runs every candidate agent on the same task list with
# the stock swegemma harness (subprocess sandbox, same as kaggle notebooks have to). only phase 1
# matters here: patches and traces come home and get graded locally by one trusted grader
# (tools/gold_check.py --mode patches), so every A/B comparison goes through the same judge.

import base64
import glob
import io
import json
import os
import subprocess
import sys
import tarfile
import time
from pathlib import Path

RUN = json.loads(base64.b64decode("__RUN_JSON_B64__"))
CANDIDATES_TGZ = "__CANDIDATES_TGZ_B64__"

T0 = time.time()
WORK = Path("/kaggle/working")


def log(*a):
    print(f"[{(time.time() - T0) / 60:6.1f}m]", *a, flush=True)


def find_dir(pattern):
    hits = sorted(glob.glob(pattern, recursive=True))
    return Path(hits[0]) if hits else None


# --- candidates ---
cand_root = WORK / "candidates"
cand_root.mkdir(parents=True, exist_ok=True)
with tarfile.open(fileobj=io.BytesIO(base64.b64decode(CANDIDATES_TGZ)), mode="r:gz") as tf:
    tf.extractall(cand_root, filter="data")
log("candidates:", sorted(p.name for p in cand_root.iterdir()))

# adapter weights come from a private dataset (kaggle_gate.py --adapters-data), not the inline tarball.
# copy each one back into its candidate and check it's the exact file we packed
import hashlib
import shutil
for cname, cinfo in RUN["candidates"].items():
    for aname, want in (cinfo.get("adapter_weights") or {}).items():
        hits = [h for h in sorted(glob.glob(f"/kaggle/input/**/{aname}/adapter_model.safetensors", recursive=True))
                if "gemma-4-developer-agent" not in h]
        got = None
        for h in hits:
            if hashlib.sha256(Path(h).read_bytes()).hexdigest() == want:
                got = h
                break
        if not got:
            raise SystemExit(f"adapter {aname} for {cname}: no file with sha256 {want[:12]} under /kaggle/input ({len(hits)} candidates)")
        shutil.copy(got, cand_root / cname / "adapters" / aname / "adapter_model.safetensors")
        log(f"adapter {aname} -> {cname} ({Path(got).stat().st_size / 1e6:.0f} MB, sha ok)")

# --- wheelhouse, same dance as the host's getting-started notebook ---
os.environ.update({
    "LITELLM_LOCAL_MODEL_COST_MAP": "True", "TRANSFORMERS_NO_TF": "1",
    "VLLM_WORKER_MULTIPROC_METHOD": "spawn", "VLLM_MEMORY_PROFILER_ESTIMATE_CUDAGRAPHS": "1",
    "VLLM_ENGINE_READY_TIMEOUT_S": "1200", "VLLM_NO_USAGE_STATS": "1", "OTEL_SDK_DISABLED": "true",
    "PYTORCH_CUDA_ALLOC_CONF": "expandable_segments:True",
})
WH = find_dir("/kaggle/input/**/gemma-4-developer-agent-wheelhouse")
TARGET = RUN.get("model") or "gemma-4-31b-it-qat-w4a16-ct"  # the alias every candidate declares; --model on the push
MODEL = find_dir(f"/kaggle/input/**/{TARGET}/*") or find_dir("/kaggle/input/models/**/2")
COMP = Path(next(p for p in sorted(glob.glob("/kaggle/input/**/tasks.jsonl", recursive=True))
                 if "gemma-4-developer-agent" in p)).parent
# RUN["data"] = a dataset slug like goth55/g4-heldout100 to run on mined tasks instead of the dev set.
# wheels and sandbox/setup.py always come from the comp data
DATA = COMP
if RUN.get("data"):
    slug = RUN["data"].split("/")[-1]
    DATA = Path(next(p for p in sorted(glob.glob("/kaggle/input/**/tasks.jsonl", recursive=True))
                     if slug in p)).parent
    # big sets ship their snapshots in ~1 GB folders (snapshots_00, snapshots_01, ...) because one
    # multi-GB zip doesn't survive the kaggle upload. link them back into one snapshots/ folder
    parts = sorted(p for p in DATA.glob("snapshots_*") if p.is_dir())
    if parts and not (DATA / "snapshots").is_dir():
        merged = Path("/tmp/g4data")
        (merged / "snapshots").mkdir(parents=True, exist_ok=True)
        for part in parts:
            for f in part.rglob("*.tgz"):  # rglob: kaggle sometimes nests an extracted zip one level down
                (merged / "snapshots" / f.name).symlink_to(f)
        for name in ("tasks.jsonl", "graphs", "embeddings"):
            if (DATA / name).exists() and not (merged / name).exists():
                (merged / name).symlink_to(DATA / name)
        log(f"merged {len(parts)} snapshot folders into {merged}/snapshots")
        DATA = merged
    # dataset uploads with --dir-mode zip may arrive as snapshots.zip etc. instead of folders
    if not (DATA / "snapshots").is_dir():
        import shutil
        import zipfile
        flat = Path("/tmp/g4data")
        flat.mkdir(parents=True, exist_ok=True)
        shutil.copy(DATA / "tasks.jsonl", flat / "tasks.jsonl")
        for sub in ("snapshots", "graphs", "embeddings"):
            z = DATA / f"{sub}.zip"
            if z.is_file():
                with zipfile.ZipFile(z) as zf:
                    zf.extractall(flat if any(n.startswith(f"{sub}/") for n in zf.namelist()) else flat / sub)
        DATA = flat
TASKS = DATA / "tasks.jsonl"
if RUN.get("tasks_override_b64"):
    # kaggle_gate.py shipped our local tasks.jsonl (e.g. restated problem statements); snapshots still come from DATA
    import zlib
    TASKS = Path("/tmp/g4tasks.jsonl")
    TASKS.write_bytes(zlib.decompress(base64.b64decode(RUN.pop("tasks_override_b64"))))
    log("tasks.jsonl override:", RUN.get("tasks_override"))
os.environ["KAGGLE_SANDBOX_DIR"] = str(COMP / "sandbox")
log("wheelhouse:", WH, "| model:", MODEL, "| data:", DATA, "| snapshots:", len(list((DATA / "snapshots").glob("*"))))
for pth in glob.glob("/usr/local/lib/python*/*-packages/*cutlass*.pth"):
    try:
        os.unlink(pth)
    except OSError:
        pass
tmp_whl = Path("/tmp/wheelhouse")
tmp_whl.mkdir(exist_ok=True)
for w in WH.glob("*.whl"):
    if "cutlass" in w.name.lower():
        continue
    name = w.name.replace("cu128", "+cu128") if ("cu128" in w.name and "+" not in w.name) else w.name
    if not (tmp_whl / name).exists():
        os.symlink(w, tmp_whl / name)
subprocess.run([sys.executable, "-m", "pip", "install", "-q", "--no-deps", "--force-reinstall",
                *sorted(str(w) for w in tmp_whl.glob("*.whl"))], check=True)
log("wheelhouse installed")

import asyncio  # noqa: E402

import litellm  # noqa: E402
import torch  # noqa: E402
import yaml  # noqa: E402
from adk_submission import VllmConfig, VllmServer, discover_adapters  # noqa: E402
from google.adk.agents.context_cache_config import ContextCacheConfig  # noqa: E402
from google.adk.apps._configs import EventsCompactionConfig  # noqa: E402
from swegemma.config import ALLOWED_ADAPTER_EXTENSIONS, EvalConfig, build_submission_limits  # noqa: E402
from swegemma.evaluate import Evaluator  # noqa: E402
try:
    from swegemma.models.discovery import validate_single_declared_model  # noqa: E402
except ImportError:  # swegemma 0.2.11 handed model discovery to adk_submission and dropped this helper
    from adk_submission.discovery import discover_declared_models  # noqa: E402

    def validate_single_declared_model(agent_dir):
        found = discover_declared_models(agent_dir)
        if len(found) != 1:
            raise SystemExit(f"{agent_dir}: needs exactly one declared model, found {sorted(found)}")
        return next(iter(found))
from swegemma.results import save_results  # noqa: E402

import re  # noqa: E402

from swegemma.sandbox.subprocess import SubprocessManager  # noqa: E402

litellm.drop_params = True
_SETUP_CALL = re.compile(r"python3\s+\S*setup\.py\s+--fast-path")


class WsFirstSubprocessManager(SubprocessManager):
    """Stock subprocess sandbox, plus one fix: the workspace's src/ goes first on sys.path.

    kaggle's image already has requests, click, flask, attrs... installed, and an editable install
    of a src-layout repo hooks in *after* the normal path search, so an agent running the tests
    would be testing the installed copy instead of its own edits."""

    def exec(self, sandbox_id, command, *, timeout=None):
        res = super().exec(sandbox_id, command, timeout=timeout)
        if _SETUP_CALL.search(command):
            paths = self._sandboxes[sandbox_id]
            src = paths["workspace"] / "src"
            if src.is_dir():
                for sp in paths["venv"].glob("lib/python*/site-packages"):
                    (sp / "_g4_ws_first.pth").write_text(f"import sys; sys.path.insert(0, {str(src)!r})\n")
        return res

# one server for all candidates. adapters from every candidate get registered together, so
# tools/kaggle_gate.py refuses candidates whose adapter names collide
manifests = {}
for cand in sorted(p for p in cand_root.iterdir() if p.is_dir()):
    validate_single_declared_model(cand)
    manifests[cand.name] = discover_adapters(str(cand), adapter_extensions=ALLOWED_ADAPTER_EXTENSIONS)
merged = None
for m in manifests.values():
    if m and getattr(m, "adapters", None):
        if merged is None:
            merged = m
        else:
            merged.adapters.update(m.adapters)

gpus = torch.cuda.device_count()
cfg = VllmConfig(
    model=str(MODEL), port=8000, host="127.0.0.1",
    tool_call_parser="gemma4", reasoning_parser="gemma4", max_model_len=32768,
    dtype="bfloat16", gpu_memory_utilization=0.80, enable_auto_tool_choice=True,
    enable_lora=True, max_loras=8, max_lora_rank=128,
    tensor_parallel_size=4 if gpus >= 4 else gpus, startup_timeout=60 * 20,
)
srv = VllmServer(cfg, adapter_manifest=merged)
srv.start()
log(f"vllm up ({gpus} gpus)")
models = srv.create_model_registry(aliases=[TARGET], model_prefix="openai/", api_key="EMPTY")
limits, gen_constraints = build_submission_limits()

summary = {"run": RUN, "candidates": {}}
for cand in sorted(p for p in cand_root.iterdir() if p.is_dir()):
    ev_raw = {}
    if (cand / "eval_config.yaml").is_file():
        raw = yaml.safe_load((cand / "eval_config.yaml").read_text()) or {}
        ev_raw = raw.get("evaluation", raw)
    out = WORK / "results" / cand.name
    eval_cfg = EvalConfig(
        tasks_path=TASKS,
        snapshots_dir=DATA / "snapshots",
        results_dir=out,
        submission_dir=cand,
        models=models,
        sandbox="subprocess",
        timeout_seconds=int(ev_raw.get("timeout_seconds", 300)),
        # with several tasks sharing the GPU each stream runs slower than on the sequential scorer,
        # so the gate stretches wall-clock budgets by time_scale to give each task the same compute
        max_time_minutes=(float(ev_raw["max_time_minutes"]) * RUN.get("time_scale", 1.0)
                          if "max_time_minutes" in ev_raw else None),
        max_tool_calls=int(ev_raw["max_tool_calls"]) if "max_tool_calls" in ev_raw else None,
        max_turns=int(ev_raw["max_turns"]) if "max_turns" in ev_raw else None,
        limits=limits,
        generation_constraints=gen_constraints,
        adapter_manifest=manifests[cand.name],
        # scripts/inference.py values from HARNESS_README section 7.2
        context_cache_config=ContextCacheConfig(min_tokens=2048, ttl_seconds=1800, cache_intervals=10),
        events_compaction_config=EventsCompactionConfig(
            compaction_interval=5, overlap_size=2, token_threshold=14336, event_retention_size=5),
        graph_dir=str(DATA / "graphs"),
        embeddings_dir=str(DATA / "embeddings"),
        wheels_dir=DATA / "wheels",
        task_ids=RUN["task_ids"],
        concurrency=RUN["concurrency"],
        display_mode="quiet",
    )
    t = time.time()
    log(f"== {cand.name}: {len(RUN['task_ids'])} tasks, concurrency {RUN['concurrency']}, budget {ev_raw}")
    ev = Evaluator(eval_cfg)
    ev.sandbox = ev.docker = WsFirstSubprocessManager(timeout_seconds=eval_cfg.harness.command_timeout_seconds or 300)
    res = asyncio.run(ev.run())
    save_results(res, out)  # patches/<id>.patch + task_results.jsonl, the bits we take home
    mins = (time.time() - t) / 60
    summary["candidates"][cand.name] = {"minutes": round(mins, 1), "kaggle_resolved": res.resolved,
                                        "tasks": res.total}
    log(f"== {cand.name}: {res.resolved}/{res.total} resolved on kaggle's grader, {mins:.1f} min")
    (WORK / "gate_summary.json").write_text(json.dumps(summary, indent=2))

srv.stop()
log("done")
